queries.query:
// Change to 30s, 1m, or 5m as needed
interval = 1m

from(bucket: "telemetry")
    |> range(
        start: v.timeRangeStart,
        stop: v.timeRangeStop
    )
    |> filter(fn: (r) =>
        r._measurement == "prediction" and
        r._field == "predicted_class"
    )
    |> map(fn: (r) => ({
        r with
        _value: if int(v: r._value) == 1 then 1 else 0
    }))

    // Group records by engine
    |> group(columns: ["engine_id"])

    // Divide time into separate intervals
    |> window(
        every: interval,
        createEmpty: false
    )

    // Count each engine once if it reported any alert
    |> max(column: "_value")

    // Sum alerting engines within each interval
    |> group(columns: ["_start", "_stop"])
    |> sum(column: "_value")

    // Label each interval by its start time
    |> duplicate(column: "_start", as: "_time")
    |> keep(columns: ["_time", "_value"])
    |> group()
    |> sort(columns: ["_time"])
    |> set(
        key: "_field",
        value: "Alerting Engines"
    )
    |> yield(name: "alerting_engines_by_interval")
